// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    NoReceive depositor;
    NoReceive zeroCreditCaller;

    function setUp() public { c = new ReentrancyDAO(); depositor = new NoReceive(); zeroCreditCaller = new NoReceive(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, type(uint128).max);
        vm.deal(address(depositor), amount);
        vm.prank(address(depositor));
        c.deposit{value: amount}();

        // zeroCreditCaller has never deposited: credit is zero.
        bool ok;
        vm.prank(address(zeroCreditCaller));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}

contract NoReceive {
    // intentionally has neither receive nor fallback: cannot accept ETH transfers
}
